/**
 * Chart.js local bundle for Continue Air-Gapped Connection Activity Panel.
 * Self-contained canvas chart library for line and bar trend visualization.
 */
(function(global) {
  function Chart(ctx, config) {
    this.ctx = ctx.getContext ? ctx.getContext('2d') : ctx;
    this.config = config || {};
    this.data = config.data || { labels: [], datasets: [] };
    this.render();
  }

  Chart.prototype.render = function() {
    var ctx = this.ctx;
    var canvas = ctx.canvas;
    if (!canvas) return;
    var width = canvas.width = canvas.clientWidth || 400;
    var height = canvas.height = canvas.clientHeight || 150;
    ctx.clearRect(0, 0, width, height);

    var dataset = this.data.datasets && this.data.datasets[0];
    if (!dataset || !dataset.data || dataset.data.length === 0) return;

    var data = dataset.data;
    var maxVal = Math.max.apply(null, data.concat([1]));
    var padding = 20;
    var chartW = width - padding * 2;
    var chartH = height - padding * 2;

    // Draw axes
    ctx.strokeStyle = '#3c3c3c';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Draw trend line
    ctx.strokeStyle = dataset.borderColor || '#f44747';
    ctx.fillStyle = dataset.backgroundColor || 'rgba(244, 71, 71, 0.2)';
    ctx.lineWidth = 2;

    var step = chartW / Math.max(data.length - 1, 1);
    ctx.beginPath();
    for (var i = 0; i < data.length; i++) {
      var x = padding + i * step;
      var y = height - padding - (data[i] / maxVal) * chartH;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // Fill area under line
    ctx.lineTo(padding + (data.length - 1) * step, height - padding);
    ctx.lineTo(padding, height - padding);
    ctx.closePath();
    ctx.fill();
  };

  Chart.prototype.update = function() {
    this.render();
  };

  global.Chart = Chart;
})(typeof window !== 'undefined' ? window : this);
